//! `perf-doc` (dev T9, docs V1): `docs/PERFORMANCE.md` rendered from
//! `benches/baseline.toml` and the latency targets of the root
//! `SPEC.md` C, the same bytes for the same inputs.

#[cfg(test)]
mod tests;

use std::collections::BTreeMap;
use std::fmt::Write as _;

use crate::baseline::{Row, ms};

/// The page's head: what made it and how to make it again.
const HEAD: &str = "\
# Performance

<!-- Generated by `cargo run -q -p chertmem-dev -- perf-doc`; do not edit. -->

This page is generated from `benches/baseline.toml` and the latency
targets in the root `SPEC.md`; do not edit it by hand. After a new
baseline, regenerate it with `cargo run -q -p chertmem-dev -- perf-doc`;
the commit gate's `perf-doc --check` fails while it is stale. How the
benchmarks run, what each suite measures and how the baseline is
updated: [Benchmarks](BENCHMARKS.md).

Every number is the time of 1 call in milliseconds: criterion's median
and the 95th percentile of its samples. A row passes when its median is
under its suite's target; a suite without a target is measured for
scale.
";

/// The root C latency targets, by name, in ms: the line that starts
/// `- latency targets`, items split by a spaced middle dot, each
/// `<name> < <n> ms`.
///
/// # Errors
/// No such line, or an item not of that shape.
pub fn targets(spec: &str) -> Result<BTreeMap<String, f64>, String> {
    let line = spec.lines().find(|l| l.starts_with("- latency targets"));
    let line = line.ok_or("SPEC.md states no `- latency targets` line")?;
    let (_, items) = line.split_once(": ").ok_or("no `:` after the name")?;
    let items = items.trim_end_matches('.').split(" \u{b7} ");
    items.map(target).collect()
}

/// `` `get_observations` < 2 ms `` -> (`get_observations`, 2).
fn target(item: &str) -> Result<(String, f64), String> {
    let bad = || format!("target `{item}` is not `<name> < <n> ms`");
    let (name, limit) = item.split_once(" < ").ok_or_else(bad)?;
    let n = limit.strip_suffix(" ms").and_then(|n| n.parse().ok());
    Ok((name.trim_matches('`').to_owned(), n.ok_or_else(bad)?))
}

/// The page for `rows`, 1 section per suite in the rows' order.
///
/// # Errors
/// A row naming a target `targets` does not hold.
pub fn render(
    rows: &[Row],
    targets: &BTreeMap<String, f64>,
) -> Result<String, String> {
    let mut page = HEAD.to_owned();
    for suite in suites(rows) {
        let of: Vec<&Row> = rows.iter().filter(|r| r.suite == suite).collect();
        section(&mut page, &of, targets)?;
    }
    Ok(page)
}

/// The suites of `rows`, each once, in order.
fn suites(rows: &[Row]) -> Vec<&str> {
    let mut seen: Vec<&str> = Vec::new();
    for r in rows {
        if !seen.contains(&r.suite.as_str()) {
            seen.push(&r.suite);
        }
    }
    seen
}

fn section(
    page: &mut String,
    rows: &[&Row],
    targets: &BTreeMap<String, f64>,
) -> Result<(), String> {
    let Some(first) = rows.first() else {
        return Ok(());
    };
    let limit = limit(first, targets)?;
    let _ = writeln!(page, "\n## {}\n\n{}\n", first.suite, says(first, limit));
    page.push_str("| fixture | median | p95 | target | pass |\n");
    page.push_str("| --- | ---: | ---: | ---: | --- |\n");
    for r in rows {
        let _ = writeln!(page, "{}", table_row(r, limit));
    }
    measured(page, rows);
    recounts(page, rows);
    Ok(())
}

/// The suite's target in ms, `None` when it has none.
fn limit(
    r: &Row,
    targets: &BTreeMap<String, f64>,
) -> Result<Option<f64>, String> {
    let Some(name) = &r.target else {
        return Ok(None);
    };
    let found = targets.get(name).copied();
    let why = || format!("{}: target `{name}` is not in SPEC.md C", r.suite);
    found.map(Some).ok_or_else(why)
}

fn says(r: &Row, limit: Option<f64>) -> String {
    match (&r.target, limit) {
        (Some(name), Some(ms)) => format!("Target: {name} under {ms} ms."),
        _ => "No latency target; measured for scale.".to_owned(),
    }
}

fn table_row(r: &Row, limit: Option<f64>) -> String {
    let (target, pass) = match limit {
        Some(t) => (format!("{t} ms"), pass(r.median_ms < t)),
        None => ("-".to_owned(), "-"),
    };
    let (median, p95) = (ms(r.median_ms), ms(r.p95_ms));
    format!(
        "| {} | {median} ms | {p95} ms | {target} | {pass} |",
        r.fixture
    )
}

fn pass(under: bool) -> &'static str {
    if under { "yes" } else { "no" }
}

/// 1 line per date and machine, naming the fixtures measured then.
fn measured(page: &mut String, rows: &[&Row]) {
    let mut runs: Vec<(String, Vec<&str>)> = Vec::new();
    for r in rows {
        let run = format!("{} on {}, {}", r.date, r.machine, r.os);
        match runs.iter_mut().find(|(k, _)| *k == run) {
            Some((_, list)) => list.push(&r.fixture),
            None => runs.push((run, vec![&r.fixture])),
        }
    }
    for (run, fixtures) in runs {
        let _ = writeln!(page, "\nMeasured {run}: {}.", fixtures.join(", "));
    }
}

fn recounts(page: &mut String, rows: &[&Row]) {
    page.push_str("\nRecount:\n\n");
    for r in rows {
        let _ = writeln!(page, "- {}: `{}`", r.fixture, r.recount);
    }
}
